import numpy as np

def pixel_rgb_to_hsv(r: int, g: int, b: int):
    rn, gn, bn = r / 255.0, g / 255.0, b / 255.0
    cmax = max(rn, gn, bn)
    cmin = min(rn, gn, bn)
    delta = cmax - cmin
    h = 0.0
    if delta > 1e-8:
        if cmax == rn:
            h = 60.0 * (((gn - bn) / delta) % 6)
        elif cmax == gn:
            h = 60.0 * (((bn - rn) / delta) + 2)
        else:
            h = 60.0 * (((rn - gn) / delta) + 4)
    s = 0.0 if cmax == 0 else delta / cmax
    return h, s, cmax

import cv2, numpy as np

def segment_red_hsv(img_rgb: np.ndarray) -> np.ndarray:
    hsv = cv2.cvtColor(img_rgb, cv2.COLOR_RGB2HSV)
    mask1 = cv2.inRange(hsv, np.array([0, 70, 50]), np.array([10, 255, 255]))
    mask2 = cv2.inRange(hsv, np.array([170, 70, 50]), np.array([179, 255, 255]))
    return cv2.bitwise_or(mask1, mask2)
